import{_ as r,l as s,o as e,c as l,v as t,p as n,x as i,d,i as I,S as T}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"四次挥手与 TIME_WAIT","description":"","frontmatter":{"title":"四次挥手与 TIME_WAIT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-time-wait.md","filePath":"cs/tcp-time-wait.md","lastUpdated":1789023840000}'),_={name:"cs/tcp-time-wait.md"};function c(p,a,A,h,E,m){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="四次挥手与-time-wait" tabindex="-1">四次挥手与 TIME_WAIT <a class="header-anchor" href="#四次挥手与-time-wait" aria-label="Permalink to &quot;四次挥手与 TIME_WAIT&quot;">​</a></h1><div class="epigraph"><p>连接的两端各自关闭发送方向；主动关闭的一方在 TIME_WAIT 里停留 2MSL，让迟到的报文自然死掉。</p><footer>—— 据 Postel, RFC 793；Kurose and Ross 对连接拆除的整理</footer></div><p><a href="/cs/tcp-handshake">上一课</a>用三次握手同步了 ISN，连接进入已建立。本课不重画 SYN 交换。缺口是拆除：TCP 是全双工，一侧 FIN 只表示「我不再发」。主动关闭方必须处理旧连接的迟到包与对端最后 ACK 的丢失。TIME_WAIT 是这份合同，不是内核随意占着端口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>握手建立的是两条方向的序号空间。关闭：FIN 与 ACK 各来一回，共四段（可合并成三次，语义仍是两边关发送）。若主动方在收到最后 ACK 后立刻释放四元组，迟到的 FIN 或数据可能被新连接（同一四元组复用）当成合法。RFC 793：在 TIME_WAIT 保持 2MSL。缺口是<strong>拆除与四元组回收</strong>，不是重传定时器公式。</p><p><span class="marginnote">MSL 是报文最大生存时间的约定。RST 可以更快拆掉，但不代替正常 FIN 对未读数据的交付。半关闭允许一边仍发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用 <code>close</code> 或 shutdown 发送方向 → 发 FIN。对端 ACK，自己还可发送直到也 FIN。主动方进入 TIME_WAIT，丢弃迟到段或应答，到期后删除控制块。重传丢失的最后 ACK 靠对端重传 FIN。本课不把同时打开/同时关闭的全部状态图画成考试默写。</p>',8)),(e(),n(T,null,{default:i(()=>[I(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E5%B7%B2%E5%BB%BA%E7%AB%8B%22%5D%20--%3E%20FIN1%5B%22%E4%B8%80%E4%BE%A7%20FIN%22%5D%0A%20%20FIN1%20--%3E%20HALF%5B%22%E5%8D%8A%E5%85%B3%E9%97%AD%22%5D%0A%20%20HALF%20--%3E%20FIN2%5B%22%E5%8F%A6%E4%B8%80%E4%BE%A7%20FIN%22%5D%0A%20%20FIN2%20--%3E%20TW%5B%22TIME_WAIT%202MSL%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TIME_WAIT 把<a href="/cs/layering-e2e">端到端</a>的「旧段不能冒充新流」落在时间上，因为 IP 没有连接 ID 世代号（后课 QUIC 才有连接标识）。端口耗尽是它的运营症状，不是协议写错。序号与重传下一课才保证数据平面可靠；拆除课只保证状态机不把尸体当新生儿。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SO_REUSEADDR 的全部平台语义当标准，不把负载均衡器上的四元组规模写成调参手册。字节如何编号、丢了如何重发，下一课。</p><p>后课默认：连接能对称关闭，主动方会在 TIME_WAIT 停留。数据可靠是另一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四次挥手关两个方向；TIME_WAIT 挡迟到段。</li><li>半关闭合法；RST 是另一条路。</li><li>序号与重传下一课。</li><li>出处：RFC 793；Kurose and Ross。</li></ul>',7))])}const N=r(_,[["render",c]]);export{f as __pageData,N as default};
